EXPORT ZZT_FRACSHAPE()
BEGIN
  LOCAL R:=L1(1),I:=L1(2),U:=L1(3),E:=L1(4),D:=L1(5);
  RETURN {{TYPE(R),ROUND(R,8)},{TYPE(I),ROUND(RE(I),8),ROUND(IM(I),8)},
          {TYPE(U),U},{TYPE(E),STRING(E),TYPE(approx(E))},{TYPE(D),D,INSTRING(D,CHAR(10))}};
END;

